void durableFile(const std::filesystem::path& target,const std::string& bytes){
 if(bytes.size()>32*1024*1024)throw std::runtime_error("Recovery file exceeds 32 MiB; finish or freeze this session");
 auto temporary=target;temporary+=L".tmp";
 HANDLE file=CreateFileW(temporary.c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_WRITE_THROUGH,nullptr);
 if(file==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot create Physics recovery file");
 DWORD written=0;bool ok=WriteFile(file,bytes.data(),DWORD(bytes.size()),&written,nullptr)&&written==bytes.size()&&FlushFileBuffers(file);CloseHandle(file);
 if(!ok||!MoveFileExW(temporary.c_str(),target.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Physics recovery file publication failed");
}
// Max serializes its unit conversion through finite-precision host data.
// Permit only recapture roundoff; topology, integer IDs and stored solver inputs stay exact.
bool sameUnit(double a,double b){return std::abs(a-b)<=2e-7*std::max(std::abs(a),std::abs(b));}
bool sameCaptured(const Json& a,const Json& b){
 if(a.is_number_float()&&b.is_number_float()){double x=a.get<double>(),y=b.get<double>();return std::abs(x-y)<=1e-8+1e-6*std::max(std::abs(x),std::abs(y));}
 if(a.type()!=b.type()||a.size()!=b.size())return false;
 if(a.is_object()){for(auto it=a.begin();it!=a.end();++it)if(!b.contains(it.key())||!sameCaptured(it.value(),b.at(it.key())))return false;return true;}
 if(a.type()==Json::value_t::array){for(std::size_t i=0;i<a.size();++i)if(!sameCaptured(a[i],b[i]))return false;return true;}return a==b;
}
Vec vec(Point3 p){return{p.x,p.y,p.z};}
Point3 point(Vec p){return{float(p.x),float(p.y),float(p.z)};}
std::string narrow(const MCHAR* text){if(!text)return{};int count=WideCharToMultiByte(CP_UTF8,0,text,-1,nullptr,0,nullptr,nullptr);std::string out(count,'\0');WideCharToMultiByte(CP_UTF8,0,text,-1,out.data(),count,nullptr,nullptr);out.pop_back();return out;}
std::wstring wide(const std::string& text){int count=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,text.data(),int(text.size()),nullptr,0);if(count<=0&&!text.empty())throw std::runtime_error("Invalid UTF-8");std::wstring out(count,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,text.data(),int(text.size()),out.data(),count);return out;}
Value* textValue(const std::string& text){if(text.size()>32768){auto* value=static_cast<Value*>(globals->get(Name::intern(_T("heapfree"))));if(!value||!is_systemglobalthunk(value))throw std::runtime_error("MAXScript heap admission is unavailable");auto free=value->eval()->to_int64();std::uint64_t needed=text.size()*4+8*1024*1024;if(free<0||std::uint64_t(free)<needed)throw std::runtime_error("More free MAXScript memory is needed to preserve Undo while returning this recipe. Save the MAX scene or reduce the population; result preserved.");}return new String(wide(text).c_str());}
struct State {cpl::Input input;std::vector<cpl::Row> rows;std::vector<cpl::Birth> recipe;Vec origin;double metersPerUnit=1;std::uint64_t nextId=1,gesture=1,revision=1;
 std::string solverProfile="cpl-leaf-3";bool settled=true;State(){input.sources.push_back(cpl::boxSource({.05,.025,.002}));}};
Json encode(const State& s){Json j={{"schema",2},{"engine","jolt-1b2e77e3"},{"solver_profile",s.solverProfile},{"settled",s.settled},{"input",cpl::encodeInput(s.input)},{"rows",Json::array()},{"births",Json::array()},{"origin",{s.origin.x,s.origin.y,s.origin.z}},{"metersPerUnit",s.metersPerUnit},{"nextId",s.nextId},{"gesture",s.gesture},{"revision",s.revision}};for(auto r:s.rows)j["rows"].push_back(cpl::encodeRow(r));for(auto b:s.recipe)j["births"].push_back(cpl::encodeBirth(b));return j;}
State decode(const Json& j){if(j.at("schema")!=1&&j.at("schema")!=2)throw std::runtime_error("Unsupported standalone Physics schema");State s;s.solverProfile=j.at("solver_profile");if(s.solverProfile!="cpl-leaf-1"&&s.solverProfile!="cpl-leaf-2"&&s.solverProfile!="cpl-leaf-3"&&s.solverProfile!="cpl-continuous-1")throw std::runtime_error("Unknown Physics solver profile");s.settled=j.value("settled",true);s.input=cpl::decodeInput(j.at("input"));if(j.at("rows").size()>5000||j.at("births").size()>5000)throw std::runtime_error("Physics payload count limit");std::set<std::uint64_t> ids;for(auto r:j.at("rows")){auto row=cpl::decodeRow(r);if(row.source>=s.input.sources.size()||!ids.insert(row.id).second)throw std::runtime_error("Invalid saved source/identity");s.rows.push_back(row);}for(auto b:j.at("births"))s.recipe.push_back(cpl::decodeBirth(b));auto p=j.at("origin");s.origin={p[0],p[1],p[2]};s.metersPerUnit=j.at("metersPerUnit");s.nextId=j.at("nextId");s.gesture=j.at("gesture");s.revision=j.at("revision");if(!std::isfinite(s.metersPerUnit)||s.metersPerUnit<=0||!std::isfinite(cpl::length(s.origin))||s.nextId==0||s.gesture==0)throw std::runtime_error("Invalid saved frame/identity");for(auto r:s.rows)if(r.id>=s.nextId)throw std::runtime_error("Saved identity counter is invalid");return s;}
class ResultRestore:public RestoreObj {SingleRefMaker lifetime;Document* doc;std::shared_ptr<State> before,after;public:ResultRestore(Document*,std::shared_ptr<State>,std::shared_ptr<State>);void Restore(int)override;void Redo()override;int Size()override{return int(sizeof(*this));}MSTR Description()override{return _T("Physics Lab result");}};
