cpl::Mesh capture(INode* node,double unit,Vec origin,bool source){if(!node)throw std::runtime_error("Missing mesh binding");auto time=GetCOREInterface()->GetTime();Object* object=node->EvalWorldState(time).obj;if(!object||!object->CanConvertToType(triObjectClassID))throw std::runtime_error("Binding cannot be triangulated");auto* tri=static_cast<TriObject*>(object->ConvertToType(time,triObjectClassID));if(!tri)throw std::runtime_error("Triangulation failed");cpl::Mesh output;
 try{auto& mesh=tri->GetMesh();if(mesh.numVerts>200000||mesh.numFaces>200000)throw std::runtime_error("Mesh admission exceeded");auto tm=node->GetObjectTM(time);bool mirrored=tm.Parity()!=FALSE;Vec pivot=source?vec(node->GetNodeTM(time).GetTrans()):origin;
  for(int i=0;i<mesh.numVerts;++i){auto p=mesh.verts[i];Vec world=vec(tm.GetRow(0))*p.x+vec(tm.GetRow(1))*p.y+vec(tm.GetRow(2))*p.z+vec(tm.GetRow(3));output.vertices.push_back((world-pivot)*unit);}
  for(int i=0;i<mesh.numFaces;++i){output.faces.push_back({mesh.faces[i].v[0],mesh.faces[i].v[mirrored?2:1],mesh.faces[i].v[mirrored?1:2]});output.smoothing.push_back(mesh.faces[i].getSmGroup());}
  if(source&&mesh.mapSupport(1)){for(int i=0;i<mesh.getNumMapVerts(1);++i)output.uv.push_back(vec(mesh.mapVerts(1)[i]));for(int i=0;i<mesh.numFaces;++i){auto& f=mesh.mapFaces(1)[i];output.uvFaces.push_back({f.t[0],f.t[mirrored?2:1],f.t[mirrored?1:2]});}}
 }catch(...){if(tri!=object)tri->DeleteThis();throw;}if(tri!=object)tri->DeleteThis();return output;}
