 unsigned visibleSlot(int index)const{std::array<unsigned,64> slots{};unsigned count=0;for(unsigned i=0;i<sourceCount;++i)if(policies[i].listed)slots[count++]=i;if(index<0||unsigned(index)>=count)throw std::runtime_error("Select a valid model");std::sort(slots.begin(),slots.begin()+count,[&](unsigned a,unsigned b){return policies[a].order==policies[b].order?a<b:policies[a].order<policies[b].order;});return slots[index];}
 bool usedSource(unsigned slot)const{return std::any_of(state->rows.begin(),state->rows.end(),[&](auto r){return r.source==slot;})||std::any_of(state->recipe.begin(),state->recipe.end(),[&](auto r){return r.source==slot;});}
