 static bool equalMesh(const cpl::Mesh& a,const cpl::Mesh& b){auto vectors=[](const auto& x,const auto& y){return x.size()==y.size()&&std::equal(x.begin(),x.end(),y.begin(),[](Vec p,Vec q){return p.x==q.x&&p.y==q.y&&p.z==q.z;});};return vectors(a.vertices,b.vertices)&&vectors(a.uv,b.uv)&&a.faces==b.faces&&a.uvFaces==b.uvFaces&&a.smoothing==b.smoothing;}
