  if(old&&old->policy==cookPolicy&&old->thickness==authored.thickness&&equalMesh(old->source.render,render)){++sourceCacheHits;auto out=old->source;out.weight=policy.enabled?1:0;return out;}
  auto start=std::chrono::steady_clock::now();trace("source.cook.enter",{{"slot",slot},{"quality",policy.quality},{"pieces",policy.pieces},{"vertices",render.vertices.size()}});
  cpl::Source cooked;try{cooked=cpl::qualitySource(std::move(render),authored.thickness,policy.quality,policy.pieces,policy.volumeError);cpl::joltValidateSource(cooked,authored.thickness);}catch(const std::exception& e){trace("source.cook.error",{{"slot",slot},{"model",narrow(refs[slot]->GetName())},{"message",e.what()}});throw std::runtime_error("Model '"+narrow(refs[slot]->GetName())+"': "+e.what());}
