ResultRestore::ResultRestore(Document* d,std::shared_ptr<State> a,std::shared_ptr<State> b):doc(d),before(std::move(a)),after(std::move(b)){lifetime.SetRef(d);}
BindingRestore::BindingRestore(Document* d,unsigned i,INode* node,INode* proxy,SourcePolicy policy,unsigned count):document(d),slot(i),beforeCount(d->sourceCount),afterCount(count),before(d->policies[i]),after(policy){lifetime.SetRef(d);beforeNode.SetRef(d->refs[i]);beforeProxy.SetRef(d->refs[64+i]);afterNode.SetRef(node);afterProxy.SetRef(proxy);}
void BindingRestore::apply(bool redo){document->ReplaceReference(slot,redo?afterNode.GetRef():beforeNode.GetRef());document->ReplaceReference(64+slot,redo?afterProxy.GetRef():beforeProxy.GetRef());document->sourceCount=redo?afterCount:beforeCount;document->policies[slot]=redo?after:before;document->sourceCache[slot].reset();document->stale=true;document->changed();}
ColliderRestore::ColliderRestore(Document* d,unsigned i,INode* node,unsigned count):document(d),slot(i),beforeCount(d->colliderCount),afterCount(count){lifetime.SetRef(d);beforeNode.SetRef(d->refs[128+i]);afterNode.SetRef(node);}
void ColliderRestore::apply(bool redo){document->ReplaceReference(128+slot,redo?afterNode.GetRef():beforeNode.GetRef());document->colliderCount=redo?afterCount:beforeCount;document->stale=true;document->changed();}
PolicyRestore::PolicyRestore(Document* d,Policies a,Policies b):document(d),before(a),after(b){lifetime.SetRef(d);}
void PolicyRestore::Restore(int){document->policies=before;document->stale=true;document->changed();}
void PolicyRestore::Redo(){document->policies=after;document->stale=true;document->changed();}
int BindingPatch::Proc(RemapDir& remap){for(int i=0;i<int(original.size());++i)if(original[i]){auto* mapped=remap.FindMapping(original[i]);copy->ReplaceReference(i,mapped?mapped:original[i]);}return 0;}
void ResultRestore::Restore(int){if(!doc->publishing)doc->stop();doc->state=before;doc->prepareCollisionDisplay(doc->hasPending()?*doc->staged:*doc->state);doc->changed();}void ResultRestore::Redo(){doc->stop();doc->state=after;doc->prepareCollisionDisplay(*doc->state);doc->changed();}
void sceneEvent(void* pointer,NotifyInfo* info){auto* d=static_cast<Document*>(pointer);d->trace("scene.notification",{{"code",info->intcode}});
 if(info->intcode==NOTIFY_SCENE_PRE_DELETED_NODE){auto* node=GetNotifyParam<NOTIFY_SCENE_PRE_DELETED_NODE>(info);if(!node||node->GetHandle()!=d->ownerHandle)return;}
 try{if(info->intcode==NOTIFY_FILE_PRE_SAVE||info->intcode==NOTIFY_PRE_RENDER||info->intcode==NOTIFY_SCENE_PRE_UNDO||info->intcode==NOTIFY_SCENE_PRE_REDO){if(d->live)d->pauseLive(true);else if(d->session)d->batchPaused=true;}else{d->setViewportIcon(false,nullptr,d->iconSize);d->setCollisionDisplay(false,nullptr);d->stop(false);}}
 catch(const std::exception& e){d->error=e.what();d->trace("scene.notification.error",{{"message",e.what()}});}
}
